import {supabase,currentUser} from './auth-client.mjs';
const root=new URL('.',import.meta.url);let revision=0;
async function refresh(){const id=++revision;document.querySelectorAll('[data-admin-entry]').forEach(n=>n.remove());const user=await currentUser();if(!user||id!==revision)return;const {data,error}=await supabase.rpc('is_site_admin');if(id!==revision||error||data!==true)return;const logout=document.querySelector('#logout');if(!logout)return;document.querySelectorAll('[data-admin-entry]').forEach(n=>n.remove());let actions=logout.closest('.account-actions');if(!actions){actions=document.createElement('div');actions.className='account-actions';actions.style.cssText='display:flex;align-items:center;gap:10px;flex-wrap:wrap';logout.before(actions);actions.append(logout);}const button=document.createElement('button');button.type='button';button.dataset.adminEntry='true';button.textContent='Open dashboard';button.onclick=()=>location.assign(new URL('./admin.html',root));actions.prepend(button);}
supabase.auth.onAuthStateChange(()=>setTimeout(()=>refresh().catch(()=>{}),0));refresh().catch(()=>{});
